class Apprentice {
  constructor(name, craft) {
    this.name = name;
    this.craft = craft;
  }

  introduce() {
    console.log(`I am ${this.name}, training in ${this.craft}.`);
  }
}

const first = new Apprentice("Mira", "swordsmithing");
first.introduce();

